test('genuine inspector Close restores the qualified newly rendered task opener and preserves later focus intent',async()=>{const {installHTMLDocument}=await import('./helpers/html_dom.mjs'),{createInspector}=await import('../src/laplace/web/static_shared/workspace-inspector.mjs'),env=installHTMLDocument();try{const main=document.createElement('main'),old=document.createElement('button');old.dataset.control='task:trail';old.dataset.controlOwner='p::task';main.append(old);document.body.append(main);old.focus();const inspector=createInspector(),dialog=document.createElement('dialog'),close=document.createElement('button');dialog.append(close);document.body.append(dialog);inspector.adopt(dialog,{returnFocus:{root:main,coordinate:{control:'task:trail',owner:'p::task'},isCurrent:()=>true}});dialog.showModal();const next=document.createElement('button');next.dataset.control='task:trail';next.dataset.controlOwner='p::task';main.replaceChildren(next);close.focus();dialog.close();assert.equal(document.activeElement,next);next.focus();const second=document.createElement('dialog');document.body.append(second);inspector.adopt(second,{returnFocus:{root:main,coordinate:{control:'task:trail',owner:'p::task'},isCurrent:()=>true}});second.showModal();const later=document.createElement('button');document.body.append(later);later.focus();second.close();assert.equal(document.activeElement,later);}finally{env.restore();}});
test('root trail Close replaces native project-section fallback with its exact opener, unless a later outside intent intervenes',async()=>{const {installHTMLDocument}=await import('./helpers/html_dom.mjs'),{createInspector}=await import('../src/laplace/web/static_shared/workspace-inspector.mjs');for(const later of ['none','focus','gesture']){const env=installHTMLDocument();try{const project=document.createElement('section');project.id='project-work';project.tabIndex=-1;project.scrollTop=20;const reader=document.createElement('section'),opener=document.createElement('button');opener.textContent='What led here';opener.dataset.control='task:trail';opener.dataset.controlOwner='garden-study::WORK-evidence-trail';reader.append(opener);project.append(reader);document.body.append(project);opener.focus();const inspector=createInspector(),dialog=document.createElement('dialog'),close=document.createElement('button');dialog.append(close);document.body.append(dialog);inspector.adopt(dialog,{returnFocus:{root:reader,coordinate:{control:'task:trail',owner:'garden-study::WORK-evidence-trail'},isCurrent:()=>true}});dialog.showModal();close.focus();document.dispatchEvent({type:'focusin',target:close});const next=opener.cloneNode(true);reader.replaceChildren(next);dialog.open=false;project.scrollTop=91;project.focus();document.dispatchEvent({type:'focusin',target:project});let expected=next;if(later==='focus'){const text=document.createElement('textarea');text.value='Later unsent Ω';document.body.append(text);text.focus();document.dispatchEvent({type:'focusin',target:text});expected=text;}if(later==='gesture'){document.dispatchEvent({type:'pointerdown',target:project});expected=project;}dialog.dispatchEvent({type:'close'});assert.equal(document.activeElement,expected,later);assert.equal(project.scrollTop,later==='none'?20:91,'later author intent keeps its scroll as well as focus');assert.equal(next.isConnected,true);assert.equal(next.disabled,false);}finally{env.restore();}}});
test('directed edges meet visible rectangle boundaries in either rank direction and across horizontal cards',async()=>{const {topologyEdgeGeometry,CARD}=await import('../src/laplace/web/static_shared/workspace-topology.mjs');for(const [a,b]of [[{x:114,y:174},{x:114,y:50}],[{x:114,y:50},{x:114,y:174}],[{x:114,y:50},{x:400,y:50}]]){const edge=topologyEdgeGeometry(a,b),inside=(p,c)=>Math.abs(p.x-c.x)<CARD.w/2&&Math.abs(p.y-c.y)<CARD.h/2;assert.equal(inside(edge.start,a),false);assert.equal(inside(edge.end,b),false);assert.ok((b.x-edge.end.x)*(b.x-a.x)+(b.y-edge.end.y)*(b.y-a.y)>0,'arrow approaches the target from source side');assert.ok(edge.d.endsWith(edge.end.x+','+edge.end.y));}const up=topologyEdgeGeometry({x:114,y:174},{x:114,y:50});assert.ok(up.start.y<174-CARD.h/2);assert.ok(up.end.y>50+CARD.h/2,'upwards Requires arrow ends below target bottom, not behind its top');});

