test('Work view generic read: Cancel releases the opener and returns focus to it, a failure is reported once and Retry carries focus to the fresh Cancel, a same-Work background update keeps the pending read and the dirty draft, and a settled row focuses its heading',async()=>{
 const {installHTMLDocument}=await import('./helpers/html_dom.mjs'),{mountOperatorWork}=await import('../src/laplace/web/static_shared/workspace-work.mjs'),env=installHTMLDocument();let work;
 try{const tick=()=>new Promise(r=>setTimeout(r,0)),id='WORK-public',cut='sha256:'+'d'.repeat(64),task={id,title:'Public task',goal:'Keep the answer',status:'open',recorded_status:'open',lifecycle:{status:'open',closed:false,completed:false},readiness:{status:'READY'},current_acceptance:{status:'NOT_REQUIRED'}};
  const detail={project:'p',view:'detail',read_cut:{revision:cut},task,blockers:[],children:{items:[]},dependants:{items:[]},allowed_actions:{task:{operation:'task',permitted:true,payload:{id,expected_work_revision:cut},http:{method:'POST',url:'/work/task'}},review_setup:{permitted:true,operation:'work_delivery',payload:{action:'review-setup',work_id:id},http:{method:'GET',url:'/work/delivery?project=p&request=%7B%22action%22%3A%22review-setup%22%7D'}}},action_context:{actions:[{name:'task',operation:'task',permitted:true},{name:'review_setup',operation:'work_delivery',permitted:true}]}};
  const pending=[];const request=async(url,payload,options)=>{if(payload!==undefined)throw Error('this walk never writes: '+url);if(String(url).startsWith('/work/delivery'))return new Promise((resolve,reject)=>pending.push({resolve,reject,signal:options?.signal||null}));return structuredClone(detail);};
  const host=document.createElement('main');document.body.append(host);work=await mountOperatorWork(host,{project:'p',summary:{tasks:[task]},initialWork:id,request});
  const inspect=()=>host.querySelectorAll('button').find(b=>b.textContent==='review setup · inspect'),cancelButton=()=>host.querySelectorAll('button').find(b=>b.textContent==='Cancel this read');
  // 1. Cancel: the exact GET is aborted, the opener was released at once and takes focus back; the cancelled read reports nothing
  inspect().focus();await inspect().onclick();await tick();assert.equal(inspect().disabled,false,'the opener is released while the read is pending');assert.equal(pending.length,1);
  cancelButton().focus();cancelButton().onclick();assert.equal(pending[0].signal?.aborted,true,'only the exact GET is cancelled');assert.equal(document.activeElement,inspect(),'focus returns to the released opener');assert.equal(host.querySelector('[data-work-read]'),null);
  pending[0].reject(Error('aborted'));await tick();assert.equal(host.querySelectorAll('.error').length,0,'a cancelled read reports nothing');
  // 2. failure: one report kept in place with Retry; focus moves from the removed Cancel to Retry, then to the fresh row's Cancel
  await inspect().onclick();await tick();cancelButton().focus();pending[1].reject(Error('owner refused'));await tick();await tick();
  const retry=host.querySelectorAll('button').find(b=>b.textContent==='Retry this read');assert.ok(retry,'Retry is offered');assert.equal(document.activeElement,retry,'the stranded Cancel focus lands on Retry');assert.equal(host.querySelectorAll('.error').length,1,'the failure is reported once');
  retry.onclick();await tick();assert.equal(pending.length,3,'Retry issues the identical read');assert.equal(host.querySelectorAll('[data-work-read]').length,1,'the failed row is replaced by one fresh pending row');assert.equal(document.activeElement,cancelButton(),'focus carries to the fresh Cancel');
  // 3. a same-Work background update keeps the pending read and the dirty draft; the settled row then focuses its heading
  const editor=host.querySelector('.operator-work-editor');editor.open=true;const title=editor.querySelector('input[name="title"]');title.value='Unsent title Ω';editor.querySelector('form').oninput();await tick();
  await work.observed({});await tick();assert.equal(host.querySelector('input[name="title"]').value,'Unsent title Ω','the dirty draft survives the background update');assert.ok(host.querySelector('[data-work-read="pending"]'),'the pending read survives the background update');
  pending[2].resolve({action:'review-setup',work_id:id,says:'settled body'});await tick();await tick();
  const read=host.querySelector('[data-work-read="read"]');assert.ok(read,'the read settles in its slot');assert.match(read.textContent,/settled body/);assert.equal(document.activeElement,read.querySelector('h4'),'a settled row has a valid focus destination');
 }finally{work?.destroy();env.restore();}
});
