test('Artifact Partial shows the actual painted scalar range and names the next requested range; a duplicate Continue issues no second GET, every page is read at the exact pin, and the terminal page relabels',async()=>{
 const env=installDOM(),reader=await loadReader();try{
  const a='π🌱 first ',b='second 中',pin='b'.repeat(64),total=Array.from(a).length+Array.from(b).length,big=3*1024*1024,calls=[];let hold=null;
  assert.equal(total,17);assert.notEqual(Buffer.byteLength(a+b),total,'UTF-8 bytes and scalar counts differ on purpose');
  const page=(content,offset,next)=>({path:'big.txt',scope:'project',content,offset,next_offset:next,total_chars:total,bytes:big,sha256:pin});
  const request=async url=>{calls.push(url);const q=new URL(url,'http://local'),offset=Number(q.searchParams.get('offset')||0);if(offset===0)return page(a,0,9);return new Promise(resolve=>{hold=()=>resolve(page(b,offset,null));});};
  const dialog=await reader.openArtifact({project:'p',path:'big.txt',scope:'project',expectedSha256:pin,request});
  const extent=dialog.all().find(n=>n.dataset?.extent);assert.equal(extent.dataset.extent,'partial');assert.match(extent.textContent,/^Partial · characters 0–9 of 17 · read at /);assert.doesNotMatch(extent.textContent,/3145728/,'whole-file bytes are not the painted extent');
  const next=findButton(dialog,'Continue: characters 9–17 of 17');assert.ok(next,'Continue names the next requested scalar range');
  const first=next.onclick(),second=next.onclick();await Promise.resolve();assert.equal(calls.filter(u=>u.includes('offset=9')).length,1,'a duplicate click issues no second GET');assert.equal(next.disabled,true);
  hold();await first;await second;assert.match(extent.textContent,/^Partial · characters 9–17 of 17 · read at /);assert.equal(next.textContent,'End of text reached');assert.equal(next.disabled,true);
  assert.ok(calls.every(u=>u.includes('expected_sha256='+pin)),'every page is read at the exact pin');
  findButton(dialog,'Close').onclick();assert.equal(dialog.isConnected,false);
 }finally{reader.destroy();env.restore();}
});
