test('Home All activity clears earlier recorded filters and preserves the existing leave decision',async()=>{const {installHTMLDocument}=await import('./helpers/html_dom.mjs'),{mountActivity}=await import('../src/laplace/web/static_shared/workspace-activity.mjs'),env=installHTMLDocument(),priorFetch=globalThis.fetch;try{const root=document.createElement('main'),host=document.createElement('section');root.append(host);document.body.append(root);const calls=[],shown=[];let allowed=false;globalThis.fetch=async url=>{calls.push(url);return {ok:true,status:200,headers:{get:()=> 'application/json'},json:async()=>({items:[],pagination:{total:0,next_offset:null}})};};const activity=mountActivity('p',{start:{category:'manuscript',actor:'old',session_id:'old-session',scope:{file:'old.tex'},activityTab:'trace'},views:{show:(...args)=>shown.push(args)},forms:{leave:()=>allowed},ui:{root,notice(){}},discussion:{session:()=>({scope(){}})},inspect:{},place:{}});assert.equal(await activity.openAll(),false);assert.deepEqual(shown,[]);allowed=true;await activity.openAll();assert.deepEqual(shown,[['history',false]]);await activity.renderHistory(host);const read=new URL(calls.find(url=>new URL(url,'http://local').searchParams.get('view')==='activity'),'http://local');for(const field of ['file','category','actor','session_id'])assert.equal(read.searchParams.has(field),false,field+' filter is cleared');assert.ok(calls.every(url=>!url.includes('session-analytics')));activity.destroyHistory();}finally{globalThis.fetch=priorFetch;env.restore();}});

test('native Conversation decisions stay beside the composer while Options keeps infrequent controls',async()=>{const {mountShell}=await import('./helpers/shell_fixture.mjs'),s=await mountShell();try{await s.root.querySelector('[data-talk]').onclick();const options=s.root.querySelector('[data-session-options]');assert.equal(!!options.open,false);options.open=true;for(const id of ['conversation:add-document','conversation:context','conversation:next-message']){const control=s.root.querySelector('[data-control="'+id+'"]');assert.equal(control.closest('[data-session-options]'),null);assert.equal(control.hidden,false);assert.equal(control.disabled,false);}assert.ok(!s.root.querySelector('[data-mode-brief]').closest('[data-session-options]'));assert.ok(!s.root.querySelector('[data-control="conversation:target"]').closest('[data-session-options]'));}finally{s.restore();}});

test('Home action records do not imply success when the retained attempt is unknown, refused, failed or merely recorded',async()=>{const {homeActivityPresentation}=await import('../src/laplace/web/static_shared/workspace-home.mjs');for(const [status,suffix]of [['UNKNOWN','outcome unknown'],['refused','refused'],['failed','failed'],['recorded',''],['complete','']]){const value=homeActivityPresentation({event_kind:'tool-attempt',operation:'store_artifact',status});assert.match(value.sentence,/File save attempt recorded/);assert.ok(!value.sentence.includes('File result recorded'));if(suffix)assert.ok(value.sentence.includes(suffix));}for(const operation of ['read_artifact','apply_revision','task','task_status','literature_import','unrecognised'])assert.match(homeActivityPresentation({event_kind:'tool-attempt',operation,status:'UNKNOWN'}).sentence,/attempt recorded — outcome unknown/);});

test('explicit self-basis read reveals current consumed/observed conditions once, while later focus, gesture, selection or refusal wins',async()=>{const {installHTMLDocument}=await import('./helpers/html_dom.mjs'),{mountOperatorWork}=await import('../src/laplace/web/static_shared/workspace-work.mjs');for(const later of ['none','focus','gesture','selection','refusal','other-evidence']){const env=installHTMLDocument();let controller;try{const host=document.createElement('section');document.body.append(host);const read={operation:'project',payload:{namespace:'p',view:'detail',id:'task'},http:{method:'GET',url:'/work/state?project=p&view=detail&id=task'}},basis={operation:'task_status',payload:{id:'task',expected_work_scope_revision:'original-guard'},http:{method:'POST',url:'/work/transition'}},reason='Completion evidence changed',detail={project:'p',view:'detail',task:{id:'task',title:'Compare notes',recorded_status:'done',status:'blocked',lifecycle:{status:'done',completed:true,closed:true},current_acceptance:{status:'REVIEW_REQUIRED',review_required:true,reason},currentness:{status:'STALE',kind:'EVIDENCE_CHANGED',reason,consumed_revision:'saved-pin',observed_revision:'first-observation'}},allowed_actions:{task_status:{...basis,permitted:true,statuses:['ready','done']}},blockers:[{kind:'EVIDENCE_CHANGED',relation:'completion-proof',subject:{owner:'completion-evidence',project:'p',scope:'project',id:'task',qualified_id:'p::task',path:'notes-a.md'},message:reason,sentence:reason,consumed_revision:'saved-pin',observed_revision:'first-observation',clear_when:{description:'Complete explicitly on inspected current evidence.'},read_handles:[read],next_actions:[{...read,kind:'read-basis',permitted:true,purpose:'Inspect consumed/current proof; do not silently refresh or reaccept'}]}],read_cut:{revision:'old-cut'},children:{items:[]},dependants:{items:[]}};let release;const calls=[];controller=await mountOperatorWork(host,{project:'p',summary:{tasks:[]},initialWork:'task',memory:{drafts:{task:{evidence:'retained-answer.md',summary:'kept Ω',completionBasis:basis,dirty:true}}},request:async(url,payload)=>{assert.equal(payload,undefined);calls.push(url);if(calls.length===1)return structuredClone(detail);return new Promise(resolve=>release=resolve);}});const kept=structuredClone(controller.capture().drafts.task),action=host.querySelectorAll('button').find(n=>n.textContent==='See what changed');action.focus();const pending=action.onclick();assert.equal(calls.length,2,'one explicit owner GET, no body/condition fanout');const fresh=structuredClone(detail);fresh.read_cut.revision='fresh-cut';fresh.task.currentness.observed_revision='new-observation';fresh.blockers[0].observed_revision='new-observation';let outside=null;if(later==='focus'){outside=document.createElement('textarea');outside.value='Later Ω';document.body.append(outside);outside.focus();document.dispatchEvent({type:'focusin',target:outside});}if(later==='gesture'){document.body.focus();document.dispatchEvent({type:'pointerdown',target:host});}if(later==='selection'){await controller.select('other',{...fresh,task:{...fresh.task,id:'other',title:'Later selected task'},blockers:[]});}if(later==='refusal')fresh.task.id='wrong-returned-task';if(later==='other-evidence')fresh.blockers[0].subject.path='notes-b.md';release(fresh);await pending;assert.equal(calls.length,2);assert.deepEqual(controller.capture().drafts.task,kept,'original completion draft and guard remain exact');if(later==='none'){const exact=host.querySelector('[data-work-basis]'),completion=host.querySelector('.operator-completion-basis');assert.equal(exact.open,true);assert.equal(completion.open,true);assert.match(exact.textContent,/Consumed: saved-pin/);assert.match(exact.textContent,/Observed: new-observation/);assert.match(exact.textContent,/Complete explicitly on inspected current evidence/);assert.equal(document.activeElement,exact.querySelector('summary'));assert.equal(controller.detail.read_cut.revision,'fresh-cut');assert.equal(controller.detail.task.recorded_status,'done');}else{assert.ok(host.querySelectorAll('[data-work-basis]').every(n=>!n.open));assert.ok(!host.querySelector('.operator-completion-basis')?.open);if(outside)assert.equal(document.activeElement,outside);if(later==='selection')assert.equal(controller.detail.task.id,'other');if(later==='refusal')assert.equal(controller.detail.read_cut.revision,'old-cut');}}finally{controller?.destroy();env.restore();}}});
test('a different owner basis reader keeps its issued route and does not become a self-task disclosure action',async()=>{const {installHTMLDocument}=await import('./helpers/html_dom.mjs'),{mountOperatorWork}=await import('../src/laplace/web/static_shared/workspace-work.mjs'),env=installHTMLDocument();let controller;try{const host=document.createElement('section');document.body.append(host);const read={operation:'literature_scope',payload:{task_id:'task'},http:{method:'GET',url:'/projects/literature/scope?project=p&task_id=task'}},calls=[],inspected=[];controller=await mountOperatorWork(host,{project:'p',summary:{tasks:[]},initialWork:'task',onInspectOwner:async handle=>inspected.push(handle),request:async url=>{calls.push(url);return {project:'p',view:'detail',task:{id:'task',title:'Task',status:'blocked'},allowed_actions:{},blockers:[{kind:'LITERATURE_SCOPE_CHANGED',relation:'completion-proof',next_actions:[{...read,kind:'read-basis',permitted:true}],read_handles:[read]}],children:{items:[]},dependants:{items:[]}};}});await host.querySelectorAll('button').find(n=>n.textContent==='See what changed').onclick();assert.equal(calls.length,2,'one original different-owner read follows initial detail');assert.equal(calls[1],read.http.url,'no replacement self-detail GET');assert.equal(inspected.length,0,'this existing route keeps its inline owner reading dialect');assert.ok(host.querySelectorAll('[data-work-basis]').every(n=>!n.open));}finally{controller?.destroy();env.restore();}});
